    const [file, orig, t] = l.split('\t'), path = join(BIN, file);
    return fs.exists(path) ? { file, orig, t: +t, path, info: fs.stat(path) } : null;
  }).filter(Boolean);
}
const binWrite = list => fs.writeFile(BIN_INFO, list.map(e => `${e.file}\t${e.orig}\t${e.t}\r\n`).join(''));
