  const fetch32 = () => { const v = u8[pc] | (u8[pc + 1] << 8) | (u8[pc + 2] << 16) | (u8[pc + 3] << 24); pc += 4; return v; };
  const fetchS8 = () => (fetch() << 24) >> 24;
  const done = next => { f.c(next | 0); return { fn: f, len: pc - lin, n }; };
  for (;;) {
