    f.c(start | 0).gs('eip');
    let osz = d32 ? 4 : 2, asz = d32 ? 4 : 2, seg = null, rep = null;
    let b;
    for (;;) {
      b = fetch();
      if (b === 0x66) osz = osz === 4 ? 2 : 4;
      else if (b === 0x67) asz = asz === 4 ? 2 : 4;
