        f.lg(B).lg(R).op('xor').lg(C).lg(R).op('xor').op('and');
      } else {
        f.lg(B).c(m).op('and').e(EXT_U).lg(C).c(m).op('and').e(EXT_U); if (carry) { f.gg('cf').e(EXT_U).op64('add'); }
