      else { f.gg('ssb').gg('esp').c(0xffff).op('and').op('add').ld(sz).ls(loc); f.gg('esp').c(0xffff0000).op('and').gg('esp').c(sz).op('add').c(0xffff).op('and').op('or').gs('esp'); }
